-- Academy: rebuild Yachts Module 8 as "Become the Broker": 23 pages (11 with quick checks, 12 with answerable exercises
-- saved to the Broker Portfolio) + a 10-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "Become the Broker", "body": "<p><b>Can I communicate, sell and negotiate?</b></p><p>Knowing what you think is only half the job. A broker must be able to explain clearly, ask without interrogating, present without exaggerating, handle <em>\"I don't like it,\"</em> respond when a client challenges the price, and tell a client something they may not want to hear. These are not personality traits reserved for natural salespeople. They are professional skills. And they can be learned.</p><p>This module is where you begin turning your broker thinking into broker communication. You will practise how to:</p><p>&bull; open a client conversation<br/>&bull; ask better questions<br/>&bull; listen for what is really being said<br/>&bull; present a yacht in terms of client benefit<br/>&bull; conduct a professional yacht viewing<br/>&bull; handle objections<br/>&bull; communicate uncertainty<br/>&bull; negotiate without losing trust<br/>&bull; write professional follow-up<br/>&bull; move a conversation toward a clear next step</p><p>The objective is not to make you sound like a salesperson. It is to make you <b>clear, credible, useful and trustworthy.</b></p>", "q": "What is the objective of this module?", "opts": ["To turn you into a natural salesperson", "To make you clear, credible, useful and trustworthy, not to make you sound like a salesperson", "To teach you scripts to memorise", "To help you close deals faster"], "correct": 1}, {"heading": "Chapter 1: The First Client Conversation", "body": "<p><b>The first conversation sets the tone</b></p><p>A weak broker starts selling. A strong broker starts discovering. The purpose of an initial conversation is not to prove how much you know about yachts. It is to understand who the client is, why they are considering a yacht, how they imagine using it, what matters most, what concerns them, what they do not yet understand and what still needs to be discovered.</p><p><b>A useful opening</b></p><p>Instead of: <em>\"I have several fantastic 35-metre yachts available.\"</em> Try:</p><p><em>\"Before I start showing you yachts, I'd like to understand how you imagine using one. That will help me avoid showing you boats that look right on paper but aren't actually right for you.\"</em></p><p>One approach starts with inventory. The other starts with the client.</p><p><b>The five discovery areas</b></p><p>&bull; <b>1. Experience:</b> have they owned before? Have they chartered? How familiar are they with yachts?<br/>&bull; <b>2. Lifestyle:</b> who will use the yacht (family, friends, business guests)? How do they actually spend their time?<br/>&bull; <b>3. Cruising:</b> where do they want to go, how often and for how long?<br/>&bull; <b>4. Requirements:</b> cabins, outdoor space, beach club, tender, speed, crew accommodation, accessibility?<br/>&bull; <b>5. Motivation:</b> why now? What attracted them to ownership? What are they hoping it will give them, and what are they worried it might take away?</p><p><b>Follow the answer</b></p><p>If a client says <em>\"We want something easy to operate,\"</em> don't immediately write <em>easy to operate = smaller yacht.</em> Ask: <em>\"When you say easy, what part of ownership are you most concerned about?\"</em> The answer might reveal crew management, maintenance, paperwork, running costs, technical complexity, privacy or time commitment. The first answer is often only the beginning.</p>", "q": "A client says, \"We want something easy to operate.\" What should you do?", "opts": ["Assume they want a smaller yacht", "Send only the smallest yachts available", "Move straight to the price", "Ask what part of ownership they are most concerned about"], "correct": 3}, {"heading": "Exercise: The Five-Minute Opening", "body": "<p><b>Try it</b></p><p>Record yourself conducting a five-minute opening conversation. Your objective is not to recommend a yacht. Your objective is to <b>discover.</b> Afterwards, listen back and answer the five questions below.</p>", "exercise": {"intro": "Record it (or run it with a friend), then review honestly.", "groups": [{"title": "Reviewing my opening conversation", "section": "services", "fields": [{"key": "oc_who", "label": "Who did you speak with, and what was the scenario?", "type": "short", "min": 10}, {"key": "oc_talk", "label": "1. How much did I speak?", "type": "long", "min": 15}, {"key": "oc_open", "label": "2. How many open questions did I ask?", "type": "long", "min": 15}, {"key": "oc_follow", "label": "3. Did I follow up on interesting answers?", "type": "long", "min": 15}, {"key": "oc_assume", "label": "4. Did I make assumptions?", "type": "long", "min": 15}, {"key": "oc_early", "label": "5. Did I recommend anything too early?", "type": "long", "min": 15}]}]}}, {"heading": "Chapter 2: Ask Better Questions", "body": "<p><b>Questions decide the quality of the information</b></p><p>A broker's questions determine the quality of the information they receive. And the quality of the information determines the quality of the recommendation.</p><p><b>Five levels of questioning</b></p><p>&bull; <b>WHAT?</b> <em>\"What do you enjoy most when you charter?\"</em><br/>&bull; <b>WHY?</b> <em>\"Why is that particularly important to you?\"</em><br/>&bull; <b>HOW?</b> <em>\"How would you normally spend a week onboard?\"</em><br/>&bull; <b>WHAT IF?</b> <em>\"What would happen if you had to compromise on that?\"</em><br/>&bull; <b>WHICH MATTERS MORE?</b> <em>\"If you had to choose between more interior volume and a faster cruising speed, which would matter more?\"</em></p><p>The final question begins to reveal priorities.</p><p><b>Look for contradictions</b></p><p>Clients may say <em>\"We want privacy,\"</em> then <em>\"We want to host 20 people for dinner.\"</em> Those statements are not necessarily incompatible. But they require exploration. A good broker doesn't immediately decide which statement is correct. They investigate the tension:</p><p><em>\"When you say privacy, are you thinking about privacy from other guests, privacy from the crew, or simply having areas of the yacht that feel private?\"</em></p><p>That is brokerage thinking.</p>", "q": "A client says they want privacy but also to host 20 people. What does a good broker do?", "opts": ["Investigate the tension by asking what privacy means to them", "Decide which statement is correct", "Point out that the client is being inconsistent", "Ignore the second statement"], "correct": 0}, {"heading": "Exercise: Upgrade the Question", "body": "<p><b>Try it</b></p><p>Rewrite these weak questions. Turn each into a question that produces more useful information.</p>", "exercise": {"intro": "Open questions that reveal the person, not just a yes or no.", "groups": [{"title": "Better questions", "section": "services", "fields": [{"key": "uq_1", "label": "1. \"Do you want a big yacht?\"", "type": "long", "min": 20}, {"key": "uq_2", "label": "2. \"Do you care about speed?\"", "type": "long", "min": 20}, {"key": "uq_3", "label": "3. \"Do you want a beach club?\"", "type": "long", "min": 20}, {"key": "uq_4", "label": "4. \"Do you want lots of cabins?\"", "type": "long", "min": 20}, {"key": "uq_5", "label": "5. \"Is €8 million your budget?\"", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 3: Present the Yacht", "body": "<p><b>A presentation is not a listing read aloud</b></p><p>The client doesn't need to know everything. They need to understand <b>what matters to them.</b> Use this structure:</p><p><b>CLIENT NEED → YACHT FEATURE → CLIENT BENEFIT → TRADE-OFF</b></p><p>For example:</p><p><em>\"You mentioned that family time outdoors is particularly important. This yacht has a large aft deck and a substantial beach-club area, which gives your family more usable outdoor space close to the water. The trade-off is that it's not the fastest yacht in this size range.\"</em></p><p>That sounds different from: <em>\"It has a large aft deck, beach club and 18-knot cruising speed.\"</em> The second statement gives information. The first gives context.</p><p><b>Present in order of relevance</b></p><p>Don't present the yacht from bow to stern simply because that's how the specification sheet is written. Start with what matters most to the client. If the client cares about family use, outdoor living, privacy and simple ownership, your presentation should begin there.</p>", "q": "In what order should a broker present a yacht?", "opts": ["From bow to stern as on the spec sheet", "Starting with the price", "In order of what matters most to the client, not bow to stern", "Starting with the technical specifications"], "correct": 2}, {"heading": "Exercise: Three-Minute Presentation", "body": "<p><b>Try it</b></p><p>Choose one yacht from Module 7. Prepare a three-minute presentation. Include client requirement, relevant yacht feature, client benefit, one trade-off, one important unknown and a recommended next step. Record yourself if possible.</p><p>Then ask: <em>\"Did I present a yacht, or did I explain why this yacht might matter to this client?\"</em></p>", "exercise": {"intro": "Write it the way you would say it.", "groups": [{"title": "My presentation", "section": "yachts", "fields": [{"key": "tp_yacht", "label": "The yacht and the client", "type": "short", "min": 10}, {"key": "tp_need", "label": "Client requirement", "type": "long", "min": 20}, {"key": "tp_feat", "label": "Relevant yacht feature", "type": "long", "min": 20}, {"key": "tp_ben", "label": "Client benefit", "type": "long", "min": 20}, {"key": "tp_trade", "label": "One trade-off", "type": "long", "min": 20}, {"key": "tp_unk", "label": "One important unknown", "type": "long", "min": 20}, {"key": "tp_next", "label": "Recommended next step", "type": "long", "min": 20}, {"key": "tp_check", "label": "Did I present a yacht, or explain why it might matter to this client?", "type": "long", "min": 30}]}]}}, {"heading": "Chapter 4: The Yacht Viewing", "body": "<p><b>Brokerage becomes physical</b></p><p>The client is no longer looking at photographs. They are experiencing scale, movement, atmosphere, layout, noise, privacy, crew areas, storage, outdoor living and access between spaces. A broker's job is not to give a guided tour like a museum guide. It is to help the client <b>interpret the yacht.</b></p><p><b>Before the viewing</b></p><p>A professional broker prepares. Review client priorities, yacht specifications, asking price, key selling points, known limitations, important unknowns, questions requiring confirmation, viewing sequence and practical logistics. Never rely entirely on memory.</p><p><b>During the viewing</b></p><p>Don't talk continuously. Give the client room to react. Watch. Listen. Notice what they stop to look at, touch, question, ignore, photograph, discuss with each other and return to later. A client's behaviour can provide information that their words do not.</p><p><b>A simple viewing structure</b></p><p>&bull; <b>1. Set the context:</b> <em>\"You told me outdoor family living was particularly important, so I'd like us to pay attention to how the exterior spaces actually work for you.\"</em><br/>&bull; <b>2. Let the yacht speak:</b> don't immediately fill every silence.<br/>&bull; <b>3. Connect features to their needs:</b> <em>\"This is the area I thought might be particularly relevant to what you described.\"</em><br/>&bull; <b>4. Test the reaction:</b> <em>\"How does this feel compared with what you had imagined?\"</em><br/>&bull; <b>5. Explore concerns:</b> <em>\"Is there anything you've seen so far that gives you pause?\"</em><br/>&bull; <b>6. Don't defend the yacht:</b> if the client dislikes something, don't argue. Find out why.</p><p><b>Viewing rule</b></p><p>Never hide a weakness because you want the yacht to sell. If something doesn't suit the client, say so professionally:</p><p><em>\"This is one area where I think we should be careful. The yacht has excellent outdoor space, which fits your brief well, but the layout may not give you the level of separation you said you wanted. I'd like to explore that with you before we decide whether to progress.\"</em></p><p>That is not losing the sale. That is building trust.</p>", "q": "During a viewing, the client dislikes something. What should the broker do?", "opts": ["Defend the designer's choices", "Change the subject quickly", "Offer a discount on the spot", "Find out why, rather than arguing or defending the yacht"], "correct": 3}, {"heading": "Exercise: The Broker on Board", "body": "<p><b>Scenario</b></p><p>Choose a yacht from Module 7 or another publicly available listing. You are meeting the fictional clients <b>Alex and Emma</b> from Module 7: about €8m, Mediterranean use, 4 to 6 weeks in summer, two children, family and friends aboard, relaxed outdoor living, privacy, ownership that is not overly complicated, limited technical knowledge. You are conducting the first physical viewing. Allow <b>45 minutes:</b> 10 preparing, 20 for a simulated viewing, 10 for the client's hypothetical reactions and 5 for a broker debrief.</p><p>Never hide a weakness because you want the yacht to sell.</p>", "exercise": {"intro": "Simulate it from photographs, a listing, a video or verbally with another person.", "groups": [{"title": "Preparation (10 min)", "section": "yachts", "fields": [{"key": "bo_yacht", "label": "The yacht you chose", "type": "short", "min": 6}, {"key": "bo_show", "label": "Five client-specific things you want to show", "type": "long", "min": 60}, {"key": "bo_ask", "label": "Three questions you want to ask during the viewing", "type": "long", "min": 40}, {"key": "bo_conc", "label": "Two potential concerns", "type": "long", "min": 25}, {"key": "bo_verify", "label": "Two facts you need to verify", "type": "long", "min": 25}, {"key": "bo_notsuit", "label": "One reason this yacht may not suit them", "type": "long", "min": 25}]}, {"title": "Client reactions (10 min)", "section": "yachts", "fields": [{"key": "bo_r1", "label": "1. First impression (positive, negative, uncertain or needs investigation)", "type": "long", "min": 15}, {"key": "bo_r2", "label": "2. Exterior living", "type": "long", "min": 15}, {"key": "bo_r3", "label": "3. Main saloon", "type": "long", "min": 15}, {"key": "bo_r4", "label": "4. Cabins", "type": "long", "min": 15}, {"key": "bo_r5", "label": "5. Crew and service areas", "type": "long", "min": 15}, {"key": "bo_r6", "label": "6. Technical and operational considerations", "type": "long", "min": 15}]}, {"title": "Broker debrief (5 min)", "section": "yachts", "fields": [{"key": "bo_d1", "label": "What did the client appear to value?", "type": "long", "min": 20}, {"key": "bo_d2", "label": "What surprised you?", "type": "long", "min": 20}, {"key": "bo_d3", "label": "What concerns emerged?", "type": "long", "min": 20}, {"key": "bo_d4", "label": "What information is still missing?", "type": "long", "min": 20}, {"key": "bo_d5", "label": "Would you recommend progressing to the next stage? Why?", "type": "long", "min": 25}]}]}}, {"heading": "Chapter 5: Handle Objections", "body": "<p><b>An objection is information</b></p><p>Don't fight it. Use: <b>LISTEN → CLARIFY → ACKNOWLEDGE → EXPLORE → RESPOND → MOVE FORWARD.</b></p><p>&bull; <b>\"It's too expensive.\"</b> <em>\"When you say expensive, is the concern the asking price itself, the overall ownership cost, or whether you think the yacht represents value at that price?\"</em><br/>&bull; <b>\"I don't like the interior.\"</b> Don't defend the designer. Ask: <em>\"What specifically isn't working for you?\"</em><br/>&bull; <b>\"It's too big.\"</b> <em>\"Is the concern the physical size, the crew requirement, operating complexity, or simply how the yacht feels?\"</em><br/>&bull; <b>\"We should just buy new.\"</b> <em>\"What is it about new build that is particularly attractive to you?\"</em><br/>&bull; <b>\"I want to sleep on it.\"</b> <em>\"Of course. Before you do, is there anything you still feel uncertain about that I can help clarify?\"</em></p><p>The goal is understanding. Not winning an argument.</p>", "q": "A client says, \"It's too expensive.\" What is the best first move?", "opts": ["Immediately offer a discount", "Clarify what they mean: asking price, ownership cost, or value at that price", "Explain why the price is fair", "Move on to a cheaper yacht"], "correct": 1}, {"heading": "Exercise: Six Objections", "body": "<p><b>Try it</b></p><p>Respond to each objection. For each response, identify the clarification, acknowledgement, investigation, response and next step.</p>", "exercise": {"intro": "Use: listen, clarify, acknowledge, explore, respond, move forward.", "groups": [{"title": "My responses", "section": "services", "fields": [{"key": "ob8_1", "label": "1. \"It's too expensive.\"", "type": "long", "min": 50}, {"key": "ob8_2", "label": "2. \"I don't like the interior.\"", "type": "long", "min": 50}, {"key": "ob8_3", "label": "3. \"I think it's too big for us.\"", "type": "long", "min": 50}, {"key": "ob8_4", "label": "4. \"Why would we buy used?\"", "type": "long", "min": 50}, {"key": "ob8_5", "label": "5. \"I need to speak to my partner.\"", "type": "long", "min": 50}, {"key": "ob8_6", "label": "6. \"Let's just keep looking.\"", "type": "long", "min": 50}]}]}}, {"heading": "Chapter 6: Negotiate", "body": "<p><b>Negotiation begins before the offer</b></p><p>A broker needs to understand the client's priorities, flexibility and limits, what matters beyond price, the seller's position, the evidence supporting value, timing, competing opportunities, and what is known and unknown. Price is only one variable. Others may include deposit, closing date, inventory, conditions, repairs, equipment, delivery location, included items and survey findings.</p><p><b>Never promise an outcome you cannot control.</b></p>", "q": "Why is price not the only negotiation variable?", "opts": ["Because price is not negotiable", "Because other terms are decided by the seller alone", "Deposit, timing, conditions, repairs, inclusions and other terms can matter as much as price", "Because brokers should avoid discussing price"], "correct": 2}, {"heading": "Exercise: The Counter-Offer", "body": "<p><b>Negotiation exercise</b></p><p>The client wants to offer <b>€7.5 million.</b> The yacht is asking <b>€8 million.</b> The seller counters at <b>€7.8 million.</b> Before responding, answer the seven questions. Then write the broker's response to the seller.</p>", "exercise": {"intro": "Think before you write to the seller.", "groups": [{"title": "Before responding", "section": "sales", "fields": [{"key": "ng_1", "label": "1. What does the client actually want?", "type": "long", "min": 20}, {"key": "ng_2", "label": "2. Is €7.5m their opening position or their maximum?", "type": "long", "min": 20}, {"key": "ng_3", "label": "3. What evidence supports their position?", "type": "long", "min": 20}, {"key": "ng_4", "label": "4. What do you need to understand about the seller?", "type": "long", "min": 20}, {"key": "ng_5", "label": "5. What alternatives does the client have?", "type": "long", "min": 20}, {"key": "ng_6", "label": "6. What would make the client walk away?", "type": "long", "min": 20}, {"key": "ng_7", "label": "7. What should you communicate next?", "type": "long", "min": 20}]}, {"title": "Response to the seller", "section": "sales", "fields": [{"key": "ng_msg", "label": "The broker's response to the seller", "type": "long", "min": 80}]}]}}, {"heading": "Chapter 7: Professional Communication", "body": "<p><b>Every message contributes to your reputation</b></p><p>Clear beats clever. A useful structure is <b>WHAT → WHY → NEXT.</b> <b>What:</b> what happened? <b>Why:</b> why does it matter? <b>Next:</b> what needs to happen now?</p><p>Avoid: <em>\"Just following up to see if you had any thoughts.\"</em> Prefer:</p><p><em>\"I wanted to follow up on the two yachts we discussed. Based on your preference for outdoor family space, I think Yacht B merits a closer look. The main point I would like to clarify is the ownership history. If you're comfortable, I suggest we arrange a viewing and request the relevant documentation beforehand.\"</em></p><p>Specific. Useful. Actionable.</p><p><b>The six-second check</b></p><p>Before sending a professional message, ask: is it accurate? Is it necessary? Is it clear? Is the tone appropriate? Have I protected confidentiality? Is the next action obvious?</p>", "q": "Which structure does the module recommend for professional messages?", "opts": ["What, why, next", "Greeting, pitch, price", "Problem, blame, apology", "Summary, discount, deadline"], "correct": 0}, {"heading": "The Complete Broker Challenge: Michael", "body": "<p><b>The client conversation</b></p><p>You are now going to combine the skills from this module.</p><p><b>Scenario</b></p><p>Michael has never owned a yacht. He has chartered several times and is considering a yacht of approximately 30 to 35 metres. He says: <em>\"I want something impressive, but I don't want another job.\"</em> He normally charters for approximately two weeks each summer. He is unsure whether ownership makes more sense than continuing to charter.</p><p>Your job is <b>not to sell him a yacht.</b> Your job is to understand the situation well enough to advise him on the appropriate next step.</p><p><b>Timing: 75 minutes</b></p><p>&bull; <b>Part 1, preparation (10 min):</b> review the scenario and prepare your approach.<br/>&bull; <b>Part 2, client conversation (20 min):</b> conduct or write the conversation.<br/>&bull; <b>Part 3, viewing exercise (20 min):</b> choose one appropriate yacht and conduct a short simulated viewing based on what you have learned about Michael.<br/>&bull; <b>Part 4, written follow-up (15 min):</b> prepare the professional follow-up email and recommendation.<br/>&bull; <b>Part 5, self-assessment (10 min):</b> complete the reflection.</p><p><b>What you will submit</b></p><p>Opening conversation, discovery questions, follow-up questions, the \"another job\" objection, ownership versus charter, a dedicated viewing plan, a professional follow-up and a broker reflection. The next pages take you through them.</p>", "q": "What is the job in the Michael challenge?", "opts": ["To sell Michael a 35m yacht", "To understand the situation well enough to advise on the appropriate next step, not to sell him a yacht", "To convince him to stop chartering", "To recite specifications"], "correct": 1}, {"heading": "Challenge 1 to 3: Opening, Discovery and Follow-Up", "body": "<p><b>1. Opening conversation (50 to 100 words)</b></p><p>Show how you would begin the conversation.</p><p><b>2. Discovery questions</b></p><p>Prepare <b>12 questions,</b> in a logical order, covering experience, charter habits, family and guests, cruising, lifestyle, ownership expectations, maintenance concerns, budget, timing and decision-making.</p><p><b>3. Follow-up questions</b></p><p>Write <b>5 follow-up questions</b> that show you are listening rather than following a questionnaire.</p>", "exercise": {"intro": "Michael: \"I want something impressive, but I don't want another job.\"", "groups": [{"title": "1. Opening conversation", "section": "services", "fields": [{"key": "mc_open", "label": "Your opening (50 to 100 words)", "type": "long", "min": 250}]}, {"title": "2. Twelve discovery questions", "section": "services", "fields": [{"key": "mc_q1", "label": "Discovery question 1", "type": "short", "min": 15}, {"key": "mc_q2", "label": "Discovery question 2", "type": "short", "min": 15}, {"key": "mc_q3", "label": "Discovery question 3", "type": "short", "min": 15}, {"key": "mc_q4", "label": "Discovery question 4", "type": "short", "min": 15}, {"key": "mc_q5", "label": "Discovery question 5", "type": "short", "min": 15}, {"key": "mc_q6", "label": "Discovery question 6", "type": "short", "min": 15}, {"key": "mc_q7", "label": "Discovery question 7", "type": "short", "min": 15}, {"key": "mc_q8", "label": "Discovery question 8", "type": "short", "min": 15}, {"key": "mc_q9", "label": "Discovery question 9", "type": "short", "min": 15}, {"key": "mc_q10", "label": "Discovery question 10", "type": "short", "min": 15}, {"key": "mc_q11", "label": "Discovery question 11", "type": "short", "min": 15}, {"key": "mc_q12", "label": "Discovery question 12", "type": "short", "min": 15}]}, {"title": "3. Five follow-up questions", "section": "services", "fields": [{"key": "mc_f1", "label": "Follow-up question 1 (and what answer it follows)", "type": "short", "min": 15}, {"key": "mc_f2", "label": "Follow-up question 2 (and what answer it follows)", "type": "short", "min": 15}, {"key": "mc_f3", "label": "Follow-up question 3 (and what answer it follows)", "type": "short", "min": 15}, {"key": "mc_f4", "label": "Follow-up question 4 (and what answer it follows)", "type": "short", "min": 15}, {"key": "mc_f5", "label": "Follow-up question 5 (and what answer it follows)", "type": "short", "min": 15}]}]}}, {"heading": "Challenge 4 and 5: \"Another Job\" and Ownership vs Charter", "body": "<p><b>4. The \"another job\" objection</b></p><p>Respond to: <em>\"I don't want the yacht to become another job.\"</em> Then write <b>three follow-up questions.</b></p><p><b>5. Ownership vs charter</b></p><p>Michael says: <em>\"I'm still not convinced ownership is worth it. Maybe I should just keep chartering.\"</em> Write approximately <b>150 words</b> responding professionally. Do not try to force ownership. Help Michael think through the decision.</p>", "exercise": {"intro": "Do not push ownership.", "groups": [{"title": "4. \"Another job\"", "section": "services", "fields": [{"key": "aj_resp", "label": "Your response", "type": "long", "min": 100}, {"key": "aj_f1", "label": "Follow-up question 1", "type": "short", "min": 15}, {"key": "aj_f2", "label": "Follow-up question 2", "type": "short", "min": 15}, {"key": "aj_f3", "label": "Follow-up question 3", "type": "short", "min": 15}]}, {"title": "5. Ownership vs charter", "section": "services", "fields": [{"key": "oc5_text", "label": "Your response (about 150 words)", "type": "long", "min": 500}]}]}}, {"heading": "Challenge 6 and 7: Viewing Plan and Follow-Up Email", "body": "<p><b>6. Dedicated viewing plan</b></p><p>Select one yacht. Prepare a <b>10-minute viewing sequence:</b> what you would show first, why it matters to Michael, what you would ask him, what you would observe, one potential concern, one important unknown and how you would finish the viewing.</p><p><b>7. Professional follow-up</b></p><p>Write the email you would send after the conversation and viewing. Summarise your understanding of Michael's priorities, what remains unclear, your current assessment, the recommended next step and the information Michael needs to provide.</p>", "exercise": {"intro": "Use what, why, next. Do not oversell.", "groups": [{"title": "6. Viewing plan", "section": "yachts", "fields": [{"key": "vp_yacht", "label": "The yacht you selected", "type": "short", "min": 6}, {"key": "vp_first", "label": "What you would show first", "type": "long", "min": 25}, {"key": "vp_why", "label": "Why it matters to Michael", "type": "long", "min": 25}, {"key": "vp_ask", "label": "What you would ask him", "type": "long", "min": 25}, {"key": "vp_obs", "label": "What you would observe", "type": "long", "min": 25}, {"key": "vp_conc", "label": "One potential concern", "type": "long", "min": 20}, {"key": "vp_unk", "label": "One important unknown", "type": "long", "min": 20}, {"key": "vp_end", "label": "How you would finish the viewing", "type": "long", "min": 25}]}, {"title": "7. Professional follow-up email", "section": "services", "fields": [{"key": "fu_email", "label": "Your email to Michael", "type": "long", "min": 250}]}]}}, {"heading": "Challenge 8: Broker Reflection", "body": "<p><b>8. Broker reflection</b></p><p>Answer honestly.</p>", "exercise": {"intro": "Honest, not flattering.", "groups": [{"title": "Broker reflection", "section": "profile", "fields": [{"key": "br8_1", "label": "1. Where was I strongest?", "type": "long", "min": 20}, {"key": "br8_2", "label": "2. Where did I talk too much?", "type": "long", "min": 20}, {"key": "br8_3", "label": "3. What assumption did I make?", "type": "long", "min": 20}, {"key": "br8_4", "label": "4. What did I fail to discover?", "type": "long", "min": 20}, {"key": "br8_5", "label": "5. Did I try to sell too early?", "type": "long", "min": 20}, {"key": "br8_6", "label": "6. What would I do differently next time?", "type": "long", "min": 20}]}]}}, {"heading": "Assessment Rubric and Model Answers", "body": "<p><b>What the challenge assesses</b></p><p>The challenge is not assessing whether you can sound like an experienced broker. It is assessing whether you are beginning to <b>think and communicate like one.</b> The rubric moves from developing to competent to strong:</p><p>&bull; <b>Discovery:</b> from generic questions and assumptions, to covering the key areas, to a logical conversation that uncovers underlying needs.<br/>&bull; <b>Listening and follow-up:</b> from moving through questions mechanically, to relevant follow-ups, to genuine listening that explores contradictions.<br/>&bull; <b>Client understanding:</b> from repeating what the client said, to identifying needs and concerns, to distinguishing needs, preferences, motivations and unknowns.<br/>&bull; <b>Yacht presentation:</b> from listing features, to connecting features to needs, to explaining benefits while honestly presenting trade-offs.<br/>&bull; <b>Viewing skill:</b> from giving a tour or reciting specifications, to guiding attention, to using the viewing to discover reactions and test fit.<br/>&bull; <b>Objection handling:</b> from defending or dismissing, to clarifying and responding, to using objections as information and moving forward.<br/>&bull; <b>Negotiation thinking:</b> from focusing mainly on price, to identifying priorities and flexibility, to considering evidence, alternatives, limits and wider deal variables.<br/>&bull; <b>Professional communication:</b> from vague or promotional, to clear and professional, to concise, precise, credible and action-oriented.<br/>&bull; <b>Judgment and integrity:</b> from hiding uncertainty or overstating, to identifying some unknowns, to clearly separating facts, assumptions and questions to verify.<br/>&bull; <b>Next-step thinking:</b> from ending without direction, to a reasonable next step, to a specific next step connected to the evidence gathered.</p><p>A strong submission demonstrates: <b>Listen → Discover → Interpret → Present → Test → Advise → Move Forward.</b> Not: <em>Talk → Sell → Defend → Push.</em></p><p><b>Model answers</b></p><p>These are examples of the type of thinking expected. They are not scripts to copy.</p><p><b>Example opening</b></p><p><em>\"Before we look at specific yachts, I'd like to understand how you currently use yachts and what is making ownership attractive to you. You mentioned wanting something impressive but not wanting another job, so I'd particularly like to understand what you mean by that. Once I understand those priorities, we can work out whether ownership actually makes sense and, if it does, what sort of yacht deserves your attention.\"</em></p><p><b>Example discovery questions</b></p><p>&bull; How often do you currently charter?<br/>&bull; Who normally comes with you?<br/>&bull; What do you enjoy most about your charter experience?<br/>&bull; What frustrates you?<br/>&bull; Where do you normally cruise?<br/>&bull; How long would you ideally spend onboard if you owned?<br/>&bull; What does \"impressive\" mean to you?<br/>&bull; What part of ownership feels like it could become a job?<br/>&bull; How involved would you want to be personally?<br/>&bull; What level of crew interaction would you prefer?<br/>&bull; What are you comfortable investing in the yacht itself?<br/>&bull; Who else would be involved in the final decision?</p><p><b>Example response to \"another job\"</b></p><p><em>\"That's important, because ownership can mean very different things depending on how involved you want to be. Rather than assuming a larger or smaller yacht solves that problem, I'd like to understand what specifically you want to avoid. Is it managing crew, dealing with maintenance, administration, scheduling, or simply feeling responsible for the yacht? Once we understand that, we can look at ownership structures and yacht characteristics that address the concern.\"</em></p><p><b>Example ownership-vs-charter response</b></p><p><em>\"I wouldn't assume ownership is automatically better for you. If you only want two weeks a year and value complete flexibility, charter may continue to make more sense. Ownership becomes more interesting if you expect to use the yacht substantially more, want a consistent environment, have strong preferences about how the yacht is configured, or value having your own crew and belongings onboard. Before making that decision, I'd suggest we compare your expected annual use, preferred destinations, level of personal involvement and the overall cost and flexibility of both options.\"</em></p><p><b>What makes a strong submission?</b></p><p>A strong student does not necessarily know every answer. A strong student knows <b>which questions need answers.</b> Look for curiosity, listening, structure, restraint, clarity, commercial awareness, honesty about uncertainty, client empathy, practical judgment and a clear next step. The best submission may contain phrases such as <em>\"I don't know yet,\"</em> <em>\"I would need to verify that,\"</em> <em>\"There is a trade-off here\"</em> and <em>\"I wouldn't recommend deciding that yet.\"</em> Those are not signs of weakness. They are signs that you understand the limits of the information available.</p>", "q": "According to the model answer, how should you respond when Michael doubts ownership?", "opts": ["Explain why ownership is always better", "Offer him a viewing immediately", "Tell him to keep chartering", "Help him think through the decision by comparing use, involvement, cost and flexibility, without forcing ownership"], "correct": 3}, {"heading": "Broker's Notebook: Module 8", "body": "<p><b>Broker's notebook</b></p><p>Write short answers.</p>", "exercise": {"intro": "Short and honest.", "groups": [{"title": "My notebook", "section": "profile", "fields": [{"key": "n8_1", "label": "What part of client communication felt most natural to me?", "type": "long", "min": 20}, {"key": "n8_2", "label": "Where did I feel least comfortable?", "type": "long", "min": 20}, {"key": "n8_3", "label": "Do I enjoy asking questions?", "type": "long", "min": 15}, {"key": "n8_4", "label": "Do I enjoy listening for what is not being said?", "type": "long", "min": 15}, {"key": "n8_5", "label": "How comfortable am I discussing money?", "type": "long", "min": 15}, {"key": "n8_6", "label": "How comfortable am I telling someone that their preferred yacht may not be right?", "type": "long", "min": 15}, {"key": "n8_7", "label": "Do I enjoy the human side of brokerage as much as the yachts themselves?", "type": "long", "min": 15}]}]}}, {"heading": "Professional Output: My Broker Communication Playbook", "body": "<p><b>My Broker Communication Playbook</b></p><p>Create a two-page personal reference. This becomes part of your Broker Portfolio. Write five items in each box, one per line, in your own words.</p>", "exercise": {"intro": "Five per box, one per line. Make them phrases you would actually say.", "groups": [{"title": "My playbook", "section": "services", "fields": [{"key": "pb8_open", "label": "Five opening questions", "type": "long", "min": 60}, {"key": "pb8_follow", "label": "Five follow-up questions", "type": "long", "min": 60}, {"key": "pb8_uncert", "label": "Five phrases for uncertainty", "type": "long", "min": 60}, {"key": "pb8_present", "label": "Five phrases for presenting a yacht", "type": "long", "min": 60}, {"key": "pb8_obj", "label": "Five phrases for handling objections", "type": "long", "min": 60}, {"key": "pb8_neg", "label": "Five phrases for negotiation", "type": "long", "min": 60}, {"key": "pb8_diff", "label": "Five phrases for difficult conversations", "type": "long", "min": 60}, {"key": "pb8_mist", "label": "Five communication mistakes I want to avoid", "type": "long", "min": 60}]}]}}, {"heading": "Final Reflection and What Comes Next", "body": "<p><b>Module 8: final reflection</b></p><p>You have now practised one of the central realities of brokerage: <b>the broker is not simply selling the yacht.</b> The broker is helping a client make sense of a complicated decision. That requires: <b>Knowledge + Listening + Judgment + Communication + Trust.</b></p><p>Ask yourself honestly: <em>\"Do I enjoy this?\"</em> Not: <em>\"Am I already good at it?\"</em> You are learning. The more important question is whether you want to become better at it.</p><p><b>What comes next</b></p><p>You have learned how to communicate like a developing broker. Now it is time to turn that capability into a career.</p><p><b>Module 9: Build Your Career.</b> <em>Could I realistically enter this industry?</em> You will examine whether yacht brokerage is right for you, where you could fit, your transferable skills, your professional identity, target companies, how to approach the industry and how to prepare for interviews. The question changes from <em>\"Could I do this?\"</em> to <b>\"How could I enter this world?\"</b></p>", "q": "What is the question Module 9 moves to?", "opts": ["How could I enter this world?", "Could I do this?", "How do I sell a yacht?", "How do I negotiate a price?"], "correct": 0}]$json$;
  v_final jsonb := $json$[{"q": "What is the primary objective of an initial client conversation?", "opts": ["To present as many yachts as possible", "To discover who the client is, why they want a yacht, how they imagine using it and what matters most, not to prove the broker's knowledge", "To establish the broker's commission", "To close the sale quickly"], "correct": 1}, {"q": "Why should a broker avoid recommending a yacht too early?", "opts": ["Because it is based on assumptions before the client's real needs, priorities and concerns are understood", "Because clients dislike recommendations", "Because it reveals the broker's commission", "Because yachts should be recommended only in writing"], "correct": 0}, {"q": "What is the difference between a yacht feature and a client benefit?", "opts": ["They are the same thing", "A feature is the price; a benefit is the size", "A feature is a fact about the yacht; a benefit explains what it means for this client's needs, giving context", "A benefit is a technical specification"], "correct": 2}, {"q": "Why should a broker allow silence during a viewing?", "opts": ["To appear more expensive and exclusive", "To avoid answering technical questions", "To save time on the tour", "It gives the client room to react, look and think, and reveals what they notice and value"], "correct": 3}, {"q": "What can client behaviour during a viewing reveal?", "opts": ["What they stop to look at, touch, question, ignore or return to can show priorities and concerns their words do not", "Nothing beyond what they say aloud", "Only whether they will accept the asking price", "Whether the broker is well prepared"], "correct": 0}, {"q": "What should you do when a client objects to a yacht?", "opts": ["Defend the yacht's design and features", "Treat it as information: listen, clarify what specifically concerns them, acknowledge it and explore, rather than defending the yacht", "Ignore it and continue the tour", "End the viewing politely"], "correct": 1}, {"q": "Why is price not the only negotiation variable?", "opts": ["Because price is fixed by the market", "Because sellers never move on price", "Deposit, closing date, inventory, conditions, repairs, equipment and survey findings can matter as much as price", "Because other terms are decided by lawyers alone"], "correct": 2}, {"q": "What should a professional follow-up message make clear?", "opts": ["What happened, why it matters and what needs to happen next", "The broker's commission and terms", "How urgent the sale is", "Every detail of the specification"], "correct": 0}, {"q": "Why is admitting uncertainty sometimes valuable?", "opts": ["It lets the broker avoid work", "It shows the broker is inexperienced", "It reduces the client's confidence in the yacht", "It shows honesty and understanding of the limits of the information, and builds trust"], "correct": 3}, {"q": "What is the purpose of a next step?", "opts": ["To end the conversation politely", "To move the conversation forward with a clear, specific action connected to the evidence gathered", "To pressure the client to decide", "To postpone the decision indefinitely"], "correct": 1}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 8;
  if v_module is null then
    raise exception 'Yachts module 8 not found';
  end if;

  update public.academy_modules
     set title = 'Become the Broker', description = 'Can I communicate, sell and negotiate?'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
